def transform(grid):
    n = len(grid[0])
    center = next(i for i, value in enumerate(grid[0]) if value == 2)
    out = [[0 for _ in range(n)] for _ in range(n)]
    phase = center % 4
    for r in range(n):
        if r <= center:
            left, right = center - r, center + r
            if left < n:
                out[r][left] = 2
            if right < n:
                out[r][right] = 2
            lo, hi = max(0, left), min(n - 1, right)
        else:
            lo, hi = 0, n - 1
        for x in range(lo, hi + 1):
            if out[r][x] == 0 and (x - r) % 4 == phase:
                out[r][x] = 1
    return out
